import itertools
from typing import List, Dict, Tuple, Optional

def time_str_to_minutes(t: str) -> int:
    """Convert time string (e.g., '9:00AM') to minutes since midnight."""
    t = t.strip().upper()
    if 'PM' in t and not t.startswith('12'):
        hour_offset = 12
    else:
        hour_offset = 0
    t = t.replace('AM', '').replace('PM', '')
    hour, minute = map(int, t.split(':'))
    if hour == 12 and 'AM' in t.upper():
        hour = 0
    return (hour + hour_offset) * 60 + minute

def minutes_to_time_str(m: int) -> str:
    """Convert minutes since midnight to time string (e.g., '9:00AM')."""
    hour = (m // 60) % 24
    minute = m % 60
    suffix = 'AM' if hour < 12 else 'PM'
    if hour == 0:
        hour = 12
    elif hour > 12:
        hour -= 12
    return f"{hour}:{minute:02d}{suffix}"

class Friend:
    def __init__(self, name: str, location: str, start_time_str: str, end_time_str: str, min_duration: int):
        self.name = name
        self.location = location
        self.start = time_str_to_minutes(start_time_str)
        self.end = time_str_to_minutes(end_time_str)
        self.min_duration = min_duration

def simulate_schedule(start_time: int, start_loc: str, friends_order: List[Friend], travel_times: Dict[str, Dict[str, int]]) -> Tuple[bool, List[Dict]]:
    """Simulate a schedule for a given order of friends. Returns (feasible, events)."""
    events = []
    current_time = start_time
    current_loc = start_loc
    feasible = True

    for friend in friends_order:
        # Travel to friend's location
        travel_time = travel_times.get(current_loc, {}).get(friend.location, float('inf'))
        if travel_time == float('inf'):
            feasible = False
            break
        departure_time = current_time
        arrival_time = current_time + travel_time
        events.append({
            'type': 'travel',
            'from': current_loc,
            'to': friend.location,
            'departure': departure_time,
            'arrival': arrival_time,
            'duration': travel_time
        })
        # Wait if necessary
        if arrival_time < friend.start:
            wait_duration = friend.start - arrival_time
            events.append({
                'type': 'wait',
                'location': friend.location,
                'start': arrival_time,
                'end': friend.start,
                'duration': wait_duration
            })
            meeting_start = friend.start
        else:
            meeting_start = arrival_time
        # Check if we can meet for minimum duration
        if meeting_start + friend.min_duration > friend.end:
            feasible = False
            break
        meeting_end = meeting_start + friend.min_duration
        events.append({
            'type': 'meet',
            'friend': friend.name,
            'location': friend.location,
            'start': meeting_start,
            'end': meeting_end,
            'duration': friend.min_duration
        })
        current_time = meeting_end
        current_loc = friend.location

    return feasible, events if feasible else []

def find_optimal_schedule(start_time_str: str, start_loc: str, friends: List[Friend], travel_times: Dict[str, Dict[str, int]]) -> List[Dict]:
    """Find schedule that maximizes number of friends met."""
    start_time = time_str_to_minutes(start_time_str)
    best_count = 0
    best_events = []
    # Consider all subsets and permutations
    for r in range(len(friends), 0, -1):
        for subset in itertools.combinations(friends, r):
            for perm in itertools.permutations(subset):
                feasible, events = simulate_schedule(start_time, start_loc, perm, travel_times)
                if feasible and len(perm) > best_count:
                    best_count = len(perm)
                    best_events = events
        # If we found a feasible schedule with r friends, we can stop (since we go from largest subset downward)
        if best_count == r:
            break
    return best_events

def events_to_output(events: List[Dict], start_loc: str, start_time_str: str) -> List[str]:
    """Convert list of events to output strings as per required format."""
    output = [f"You start at {start_loc} at {start_time_str}."]
    for event in events:
        if event['type'] == 'travel':
            output.append(
                f"You travel to {event['to']} in {event['duration']} minutes and arrive at {minutes_to_time_str(event['arrival'])}."
            )
        elif event['type'] == 'wait':
            output.append(
                f"You wait until {minutes_to_time_str(event['end'])}."
            )
        elif event['type'] == 'meet':
            output.append(
                f"You meet {event['friend']} for {event['duration']} minutes from {minutes_to_time_str(event['start'])} to {minutes_to_time_str(event['end'])}."
            )
    return output

def main():
    # Define travel times
    travel_times = {
        'Bayview': {'Pacific Heights': 23},
        'Pacific Heights': {'Bayview': 22}
    }
    # Define friends
    friends = [
        Friend('Thomas', 'Pacific Heights', '12:15PM', '5:15PM', 105)
    ]
    # Start
    start_loc = 'Bayview'
    start_time_str = '9:00AM'

    # Find optimal schedule
    optimal_events = find_optimal_schedule(start_time_str, start_loc, friends, travel_times)

    # Generate output
    if optimal_events:
        output = events_to_output(optimal_events, start_loc, start_time_str)
        print(output)
    else:
        print("No feasible schedule found.")

if __name__ == '__main__':
    main()

import itertools

def time_to_minutes(t):
    t = t.strip().upper()
    time_part, ampm = t[:-2], t[-2:]
    hours, minutes = map(int, time_part.split(':'))
    if ampm == 'PM' and hours != 12:
        hours += 12
    if ampm == 'AM' and hours == 12:
        hours = 0
    return hours * 60 + minutes

def minutes_to_time(m):
    hours = m // 60
    minutes = m % 60
    ampm = 'AM' if hours < 12 else 'PM'
    if hours > 12:
        hours -= 12
    if hours == 0:
        hours = 12
    return f"{hours}:{minutes:02d}{ampm}"

class Friend:
    def __init__(self, name, location, start_time_str, end_time_str, min_duration):
        self.name = name
        self.location = location
        self.start = time_to_minutes(start_time_str)
        self.end = time_to_minutes(end_time_str)
        self.min_duration = min_duration

def schedule_meetings(start_location, start_time_str, friends, travel_times):
    start_time = time_to_minutes(start_time_str)
    best_schedule = []
    best_count = 0
    best_end_time = float('inf')

    n = len(friends)
    friend_indices = list(range(n))

    for k in range(1, n+1):
        for subset in itertools.combinations(friend_indices, k):
            for perm in itertools.permutations(subset):
                current_time = start_time
                current_loc = start_location
                actions = [f"You start at {start_location} at {minutes_to_time(start_time)}."]
                feasible = True
                for idx in perm:
                    friend = friends[idx]
                    travel_key = (current_loc, friend.location)
                    if travel_key in travel_times:
                        travel_time = travel_times[travel_key]
                    else:
                        feasible = False
                        break
                    arrival_time = current_time + travel_time
                    if arrival_time < friend.start:
                        wait_time = friend.start - arrival_time
                        meeting_start = friend.start
                    else:
                        wait_time = 0
                        meeting_start = arrival_time
                    if meeting_start + friend.min_duration > friend.end:
                        feasible = False
                        break
                    meeting_end = meeting_start + friend.min_duration
                    actions.append(f"You travel to {friend.location} in {travel_time} minutes and arrive at {minutes_to_time(arrival_time)}.")
                    if wait_time > 0:
                        actions.append(f"You wait until {minutes_to_time(meeting_start)}.")
                    actions.append(f"You meet {friend.name} for {friend.min_duration} minutes from {minutes_to_time(meeting_start)} to {minutes_to_time(meeting_end)}.")
                    current_time = meeting_end
                    current_loc = friend.location
                if feasible:
                    if k > best_count or (k == best_count and current_time < best_end_time):
                        best_count = k
                        best_end_time = current_time
                        best_schedule = actions
    if best_count == 0:
        return [f"You start at {start_location} at {minutes_to_time(start_time)}."]
    return best_schedule

def main():
    travel_times = {
        ('Chinatown', 'Nob Hill'): 8,
        ('Nob Hill', 'Chinatown'): 6,
    }
    friends = [
        Friend('Joshua', 'Nob Hill', '10:15AM', '1:00PM', 45),
    ]
    start_location = 'Chinatown'
    start_time = '9:00AM'

    schedule = schedule_meetings(start_location, start_time, friends, travel_times)
    print(schedule)

if __name__ == '__main__':
    main()

import itertools
from typing import List, Dict, Tuple, Optional

def format_time(minutes: int) -> str:
    """Convert minutes since midnight to a string like '9:00AM'."""
    hour = minutes // 60
    minute = minutes % 60
    if hour >= 12:
        suffix = 'PM'
        if hour > 12:
            hour -= 12
    else:
        suffix = 'AM'
        if hour == 0:
            hour = 12
    return f"{hour}:{minute:02d}{suffix}"

class Friend:
    def __init__(self, name: str, location: str, window_start: str, window_end: str, min_duration: int):
        self.name = name
        self.location = location
        self.window_start = self._time_to_minutes(window_start)
        self.window_end = self._time_to_minutes(window_end)
        self.min_duration = min_duration

    @staticmethod
    def _time_to_minutes(time_str: str) -> int:
        """Convert time string like '9:00AM' to minutes since midnight."""
        time_str = time_str.strip().upper()
        if ':' in time_str:
            hour_min, period = time_str.split(':')
            minute = int(hour_min[2:]) if len(hour_min) > 2 else int(hour_min[1:]) if len(hour_min) > 1 else 0
            hour = int(hour_min[:2]) if len(hour_min) > 2 else int(hour_min[0])
        else:
            # Handle like '5PM'
            hour = int(time_str[:-2])
            minute = 0
            period = time_str[-2:]
        if period == 'PM' and hour != 12:
            hour += 12
        elif period == 'AM' and hour == 12:
            hour = 0
        return hour * 60 + minute

def get_travel_time(loc1: str, loc2: str, travel_matrix: Dict[str, Dict[str, int]]) -> int:
    """Return travel time from loc1 to loc2. Assumes 0 if same location, else looks up in matrix."""
    if loc1 == loc2:
        return 0
    return travel_matrix.get(loc1, {}).get(loc2, float('inf'))

def find_optimal_schedule(start_loc: str, start_time_str: str, friends: List[Friend], travel_matrix: Dict[str, Dict[str, int]]) -> List[str]:
    """Return a schedule (list of action strings) that maximizes the number of friends met."""
    start_time = Friend._time_to_minutes(start_time_str)
    n = len(friends)

    # Try subsets from largest to smallest
    for k in range(n, 0, -1):
        for subset in itertools.combinations(friends, k):
            for perm in itertools.permutations(subset):
                current_loc = start_loc
                current_time = start_time
                actions = []
                feasible = True

                for friend in perm:
                    # Travel to friend's location
                    travel_time = get_travel_time(current_loc, friend.location, travel_matrix)
                    if travel_time == float('inf'):
                        feasible = False
                        break
                    if current_loc != friend.location:
                        arrival_time = current_time + travel_time
                        actions.append(f"You travel to {friend.location} in {travel_time} minutes and arrive at {format_time(arrival_time)}.")
                    else:
                        arrival_time = current_time

                    # Wait if necessary
                    if arrival_time < friend.window_start:
                        actions.append(f"You wait until {format_time(friend.window_start)}.")
                        meeting_start = friend.window_start
                    else:
                        meeting_start = arrival_time

                    # Check if meeting fits within window
                    if meeting_start + friend.min_duration > friend.window_end:
                        feasible = False
                        break

                    # Meet the friend
                    meeting_end = meeting_start + friend.min_duration
                    actions.append(f"You meet {friend.name} for {friend.min_duration} minutes from {format_time(meeting_start)} to {format_time(meeting_end)}.")

                    # Update state
                    current_time = meeting_end
                    current_loc = friend.location

                if feasible:
                    # Prepend start action
                    schedule = [f"You start at {start_loc} at {format_time(start_time)}."] + actions
                    return schedule

    # If no meetings possible, just return start action
    return [f"You start at {start_loc} at {format_time(start_time)}."]

# Define the specific problem data
travel_distances = {
    'Marina District': {'Haight-Ashbury': 16},
    'Haight-Ashbury': {'Marina District': 17}
}

friends_list = [
    Friend('Timothy', 'Haight-Ashbury', '5:00PM', '8:15PM', 60)
]

start_location = 'Marina District'
start_time = '9:00AM'

# Find and print the optimal schedule
schedule = find_optimal_schedule(start_location, start_time, friends_list, travel_distances)
print(schedule)

