import itertools
from datetime import datetime, timedelta

def minutes_to_time(minutes):
    """Convert minutes past midnight to a string like 9:00AM."""
    hour = minutes // 60
    minute = minutes % 60
    am_pm = 'AM' if hour < 12 else 'PM'
    hour12 = hour if hour <= 12 else hour - 12
    if hour12 == 0:
        hour12 = 12
    return f"{hour12}:{minute:02d}{am_pm}"

def time_to_minutes(time_str):
    """Convert time string like '9:00AM' to minutes past midnight."""
    # time_str format: e.g., '9:00AM', '1:15PM'
    time_str = time_str.strip()
    meridian = time_str[-2:]
    hour_min = time_str[:-2]
    hour, minute = map(int, hour_min.split(':'))
    if meridian == 'PM' and hour != 12:
        hour += 12
    elif meridian == 'AM' and hour == 12:
        hour = 0
    return hour * 60 + minute

def schedule_to_strings(schedule):
    """Convert a schedule (list of events) to list of descriptive strings."""
