import itertools

# Convert time to minutes since midnight
def minutes(hour, minute):
    return hour * 60 + minute

# Format minutes since midnight to readable time (e.g., 9:00AM)
def fmt_time(m):
    h = m // 60
    mi = m % 60
    if h < 12:
        suffix = "AM"
        if h == 0:
            h = 12
    else:
        suffix = "PM"
        if h > 12:
            h -= 12
    return f"{h}:{mi:02d}{suffix}"

# Friends data: name, location, window start, window end, minimum duration
