def simulate(order):
    """Simulate the schedule for a given order of friends.
    Returns (feasible, events, finish_time) where events is a list of strings."""
    current_loc = "Union Square"
    current_time = minutes(9, 0)  # 9:00 AM
    events = []
    for friend in order:
        travel = travel_times[current_loc][friend["loc"]]
        arrival = current_time + travel
        events.append(f"You travel to {friend['loc']} in {travel} minutes and arrive at {fmt_time(arrival)}.")
        start_time = max(arrival, friend["start"])
        if arrival < friend["start"]:
            events.append(f"You wait until {fmt_time(friend['start'])}.")
        if start_time + friend["min_dur"] > friend["end"]:
            return False, [], None
        events.append(f"You meet {friend['name']} for {friend['min_dur']} minutes from {fmt_time(start_time)} to {fmt_time(start_time + friend['min_dur'])}.")
        current_loc = friend["loc"]
        current_time = start_time + friend["min_dur"]
    return True, events, current_time

# Search for the best schedule (largest number of friends)
best_schedule = None
best_order = None
max_friends = len(friends)
found = False

for size in range(max_friends, 0, -1):
    for subset in itertools.combinations(friends, size):
        for perm in itertools.permutations(subset):
            feasible, events, finish = simulate(perm)
            if feasible:
                best_schedule = events
                best_order = perm
                found = True
                break
        if found:
            break
    if found:
        break

# Prepend the starting event
if best_schedule is not None:
    best_schedule.insert(0, f"You start at Union Square at {fmt_time(minutes(9,0))}.")
    # Output the schedule as a list
    print(best_schedule)
else:
    print("No feasible schedule found.")
